shots.draw_js:
clearScene();setBig(null);setEq(null);
lamps({y:280,gap:340,items:[
  {label:"Pong",sub:"几百万帧",state:"on"},
  {label:"病人",sub:"几百万个？",state:"dead"}]});
note("同一个数字，两种含义",640,420,"y");
setCap("DQN 在 Pong 上要几百万帧。<b>那完全没关系</b> —— 因为帧不要钱。");

clearScene();setEq(null);
setBig("能学到就行","收敛性保证我们已经有了");
setCap("前十讲的保证<b>全是渐近的</b> —— 没有一条说「要多少样本」。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:250,items:[
  {label:"一个状态",sub:"没有转移",state:"on"},
  {label:"m 个臂",sub:"分布未知",state:"on"},
  {label:"拉一次",sub:"得一个奖励",state:"on"},
  {label:"独立同分布",sub:"没有延迟",state:"on"}]});
note("RL 的最小形状",640,410,"y");
setCap("要问「要多少数据」，先把问题缩到<b>还剩下探索、但别的都没有</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:340,items:[
  {label:"计算效率",sub:"前十讲",state:"dead"},
  {label:"样本效率",sub:"这一块",state:"on"}]});
note("判据换了，算法也会换",640,420,"y");
setCap("判据一换，前十讲那些「收敛就好」的算法<b>会当场出局</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"能不能学到",sub:"前十讲",state:"dead"},
  {label:"要多少数据",sub:"这一块",state:"on"},
  {label:"最小装置",sub:"老虎机",state:"on"}]});
note("每个数据点是一个人",640,420,"r");
setCap("<b>指名反驳</b>：不是「能学到就行」。问题换成了<b>要多少数据</b>。");

clearScene();setBig(null);setEq(null);
note("怎么把「学得快」写成一个数",640,300,"y lg");
note("要能把早期的错记在账上",640,370,"sm lg");
setCap("要比较算法，先得有一个数。而这个数<b>必须是累积的</b>。");

clearScene();setEq(null);
setBig("看平均奖励就行","拿到的奖励高，就是学得好");
setCap("平均奖励会被<b>后期的好表现冲淡</b>，早期的代价看不见了。");

clearScene();setBig(null);
setEq("$$\\Delta_a=Q(a^*)-Q(a)\\qquad\\qquad \\mathrm{Regret}(T)=\\sum_{t=1}^{T}\\Delta_{a_t}$$","top");
note("差距",420,320,"b lg");
note("把差距加起来",880,320,"g lg");
setCap("<b>差距</b> Δ_a：这个臂比最优臂差多少。<b>遗憾</b>：把每一步的差距<b>加起来</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3],step:420,vals:[50.063,49.978,50.029,50.006],
  x:330,y:410,w:620,h:150,max:60,
  label:function(i){return ["10³","5×10³","2×10⁴","5×10⁴"][i];},
  cls:function(i){return "r";},
  fmt:function(v){return v.toFixed(1);}});
note("均匀随机的每千步遗憾",640,452,"sm");
setCap("<b>每千步遗憾平不下来</b>，累积遗憾就是一条直线 —— 这叫<b>线性遗憾</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"最终多好",sub:"渐近判据",state:"dead"},
  {label:"多快变好",sub:"遗憾",state:"on"},
  {label:"早期的错",sub:"永久记账",state:"on"}]});
note("平均会冲淡，求和不会",640,420,"y");
setCap("<b>指名反驳</b>：遗憾量的是<b>多快变好</b>，不是最终多好。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"贪心",sub:"总拉均值最高的",state:"dead"},
  {label:"ε-贪心",sub:"偶尔随机",state:"dead"},
  {label:"均匀随机",sub:"一直乱拉",state:"dead"}]});
note("三个都线性",640,420,"r");
setCap("三个最自然的做法，用上一集那把尺子一量 —— <b>全不及格</b>。");

clearScene();setEq(null);
setBig("ε-贪心已经在探索了","有探索就够了吧");
setCap("「有探索」和「探索得对」是两件事。<b>固定的 ε 永远不停</b>。");

clearScene();setBig(null);
setEq("$$\\text{每步遗憾}\\ \\longrightarrow\\ \\frac{\\varepsilon}{m}\\sum_a \\Delta_a\\ >\\ 0$$","top");
note("这是个正数，不是 0",640,320,"r lg");
setCap("固定 ε 的每步遗憾收敛到一个<b>正数</b> —— 于是累积遗憾是<b>直线</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3],step:420,vals:[6.588,5.318,5.070,5.034],
  x:330,y:350,w:620,h:150,max:8,
  label:function(i){return ["10⁴","5×10⁴","2×10⁵","5×10⁵"][i];},
  cls:function(i){return i===3?"r":"y";},
  fmt:function(v){return v.toFixed(3);}});
note("ε-贪心的每千步遗憾",640,392,"sm");
setCap("降、降、<b>停住</b> —— 停在 <b>5.034</b>，而理论值是 <b>5.00</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"贪心",sub:"45% 锁死",state:"dead"},
  {label:"固定 ε",sub:"停在正数",state:"dead"},
  {label:"要的是",sub:"探索会收",state:"on"}]});
note("探索要随把握变小",640,420,"y");
setCap("<b>指名反驳</b>：不是「有没有探索」，是<b>探索会不会随把握变小</b>。");
